public class HashService {

    // 使用的哈希算法
    private static final String ALGORITHM = "SHA-256";

    // 十六进制字符数组，用于高效转换字节数组
    private static final char[] HEX_ARRAY = "0123456789abcdef".toCharArray();

    /**
     * 计算输入数据的消息摘要（哈希值）
     * 
     * @param data 文件内容的字节数组
     * @return 哈希值的十六进制字符串表示
     * @throws UnsupportedOperationException 当SHA-256算法不支持时抛出
     */
    public String digest(byte[] data) {
        try {
            // 获取SHA-256算法的MessageDigest实例
            MessageDigest digest = MessageDigest.getInstance(ALGORITHM);

            // 计算哈希值
            byte[] hashBytes = digest.digest(data);

            // 将字节数组转换为十六进制字符串
            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            // SHA-256是Java标准库必须支持的算法，理论上不会抛出此异常
            // 但为满足需求，当算法不支持时抛出运行时异常
            throw new UnsupportedOperationException("SHA-256 algorithm not supported", e);
        }
    }

    /**
     * 将字节数组转换为十六进制字符串
     * 
     * @param bytes 哈希值字节数组
     * @return 十六进制字符串
     */
    private String bytesToHex(byte[] bytes) {
        char[] hexChars = new char[bytes.length * 2];
        for (int i = 0; i < bytes.length; i++) {
            int v = bytes[i] & 0xFF;  // 转换为无符号整数
            hexChars[i * 2] = HEX_ARRAY[v >>> 4];      // 高4位
            hexChars[i * 2 + 1] = HEX_ARRAY[v & 0x0F]; // 低4位
        }
        return new String(hexChars);
    }
}
